In Angular, a shared component is a component that can be used across multiple modules and applications. Here's a step-by-step guide on how to create a shared component:

**Method 1: Create a Shared Module**

1. Create a new module by running the command `ng generate module shared`.
2. In the `shared.module.ts` file, import the components you want to share. For example:
```ts
import { NgModule } from '@angular/core';
import { BrowserAnimationsModule } from '@angular/platform-browser/animations';
import { SharedComponentA } from './shared.component.a';
import { SharedComponentB } from './shared.component.b';

@NgModule({
  imports: [
    BrowserAnimationsModule
  ],
  declarations: [SharedComponentA, SharedComponentB],
  exports: [SharedComponentA, SharedComponentB]
})
export class SharedModule {}
```
3. In your application module (e.g., `app.module.ts`), import the shared module:
```ts
import { NgModule } from '@angular/core';
import { BrowserModule } from '@angular/platform-browser';
import { AppComponent } from './app.component';
import { SharedModule } from './shared/shared.module';

@NgModule({
  imports: [BrowserModule, SharedModule],
  declarations: [AppComponent],
  bootstrap: [AppComponent]
})
export class AppModule {}
```
4. Now you can use the shared components in any module by importing the shared module.

**Method 2: Create a Feature Module**

1. Create a new feature module by running the command `ng generate module shared-feature`.
2. In the `shared-feature.module.ts` file, import the components you want to share. For example:
```ts
import { NgModule } from '@angular/core';
import { CommonModule } from '@angular/common';
import { SharedComponentA } from './shared.component.a';
import { SharedComponentB } from './shared.component.b';

@NgModule({
  declarations: [SharedComponentA, SharedComponentB],
  exports: [SharedComponentA, SharedComponentB]
})
export class SharedFeatureModule {}
```
3. In your application module (e.g., `app.module.ts`), import the feature module:
```ts
import { NgModule } from '@angular/core';
import { BrowserModule } from '@angular/platform-browser';
import { AppComponent } from './app.component';
import { SharedFeatureModule } from './shared-feature/shared-feature.module';

@NgModule({
  imports: [BrowserModule, SharedFeatureModule],
  declarations: [AppComponent],
  bootstrap: [AppComponent]
})
export class AppModule {}
``

Here is a simple program in p5.js that draws a Mandelbrot fractal in the shape of a heart. The fractal is colored with a red-to-pink gradient.

```javascript
let angle = 0;
let scale = 0.4;
let offset = 0.2;

function setup() {
  createCanvas(windowWidth, windowHeight);
  angleMode(RADIANS);
  frameRate(30);
}

function draw() {
  background(0);

  // Rotate and translate the heart
  translate(width / 2, height / 2);
  rotate(angle);

  // Draw the heart
  noStroke();
  beginShape();
  for (let a = 0; a < TWO_PI; a += 0.01) {
    let x = sin(a) * (cos(angle + a) * scale - offset);
    let y = cos(a) * (cos(angle + a) * scale - offset);
    fill(255 * (cos(angle + a) * scale + 0.5));
    vertex(x * 100, y * 100);
  }
  endShape();

  // Increase the rotation angle
  angle += 0.01;
}
```

