using System;
using System.Net;
using System.Net.Http;
using System.Text;
using System.Threading;

class Program
{
    static void Main(string[] args)
    {
        // Création d'un objet HttpListener
        HttpListener listener = new HttpListener();

        // Configuration du serveur pour écouter les requêtes sur le port 8080
        listener.Prefixes.Add("http://localhost:8080/");

        // Démarrage du serveur
        listener.Start();

        Console.WriteLine("Serveur démarré : appuyez sur Entrée pour arrêter...");

        // Boucle infinie pour écouter les requêtes
        while (true)
        {
            HttpListenerContext context = listener.GetContext();

            // Traitement de la requête
            string requestUri = context.Request.Url.AbsolutePath;
            string response = "Hello";

            if (requestUri == "/")
            {
                response = "Bienvenue sur mon serveur HTTP!";
            }

            // Envoi de la réponse
            context.Response.Clear();
            context.Response.StatusCode = 200;
            context.Response.ContentType = "text/plain";
            byte[] buffer = Encoding.ASCII.GetBytes(response);
            context.Response.OutputStream.Write(buffer, 0, buffer.Length);
            context.Response.OutputStream.Close();
        }
    }
}
```
